const fs = require('node:fs');
const path = require('node:path');

const outDir = path.resolve(__dirname, '../examples/admin-panel');
const docsOutDir = path.resolve(__dirname, '../docs/examples/admin-panel');
const cssHref = '../../docs/assets/windform.css';
const bootstrapSrc = 'https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js';

const navGroups = [
  { label: 'Dashboard', href: 'index.html' },
  { label: 'Widgets', href: 'widgets.html' },
  { label: 'Mailbox', href: 'mailbox.html' },
  { label: 'Forms', items: [['Basic forms', 'forms.html'], ['Advanced forms', 'advanced-forms.html'], ['Plugin selects', 'plugins.html'], ['CDN starter', 'cdn-starter.html']] },
  { label: 'Data', items: [['Tables', 'tables.html'], ['Users', 'users.html'], ['Ecommerce', 'ecommerce.html'], ['Reports', 'reports.html']] },
  { label: 'Examples', items: [['Profile', 'profile.html'], ['Invoice', 'invoice.html'], ['Calendar', 'calendar.html']] },
  { label: 'UI Elements', items: [['Buttons', 'buttons.html'], ['Modals', 'modals.html'], ['Timeline', 'timeline.html']] },
  { label: 'Auth and errors', items: [['Login', 'login.html'], ['Errors', 'errors.html']] }
];

const nav = navGroups.flatMap((item) => item.items || [[item.label, item.href]]);

function attrs(active, label) {
  return label === active ? ' aria-current="page"' : '';
}

function navClass(active, label) {
  return label === active
    ? 'rounded-lg bg-background px-3 py-2.5 font-medium text-foreground shadow-sm'
    : 'rounded-lg px-3 py-2.5 font-medium text-background/70 transition-colors hover:bg-background/10 hover:text-background';
}

function shell({ title, active, body, extra = '' }) {
  const renderNav = (dismiss = false) => navGroups.map((item) => {
    if (!item.items) {
      return `<a class="${navClass(active, item.label)}" href="${item.href}"${attrs(active, item.label)}${dismiss ? ' data-bs-dismiss="offcanvas"' : ''}>${item.label}</a>`;
    }
    const open = item.items.some(([label]) => label === active);
    const children = item.items.map(([label, href]) => `<a class="rounded-md px-3 py-2 text-sm font-medium ${label === active ? 'bg-background/15 text-background' : 'text-background/65 hover:bg-background/10 hover:text-background'}" href="${href}"${attrs(active, label)}${dismiss ? ' data-bs-dismiss="offcanvas"' : ''}>${label}</a>`).join('');
    return `<details class="group rounded-lg"${open ? ' open' : ''}><summary class="flex cursor-pointer list-none items-center justify-between rounded-lg px-3 py-2.5 font-medium text-background/70 transition-colors hover:bg-background/10 hover:text-background"><span>${item.label}</span><span class="text-xs transition-transform group-open:rotate-90" aria-hidden="true">›</span></summary><div class="mt-1 grid gap-1 border-l border-background/10 ps-3">${children}</div></details>`;
  }).join('\n');
  const desktopNav = renderNav(false);
  const mobileNav = renderNav(true);

  return `<!doctype html>
<html lang="en" class="scroll-smooth">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${title} - Windform Admin</title>
    <meta name="description" content="AdminLTE 2-inspired Windform admin example page.">
    <link rel="stylesheet" href="${cssHref}">
    <script defer src="${bootstrapSrc}"></script>
  </head>
  <body class="bg-muted/40 text-foreground antialiased" data-theme="light">
    <div class="min-h-screen lg:grid lg:grid-cols-[17rem_minmax(0,1fr)]">
      <aside class="hidden min-h-screen border-r border-background/10 bg-foreground/95 p-4 text-background lg:block">
        <a class="flex items-center gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-background/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-foreground" href="index.html" aria-label="Windform admin home"><span class="inline-flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary font-bold text-primary-foreground shadow-sm">WF</span><span><span class="block font-semibold text-background">Windform Admin</span><span class="block text-sm text-background/70">AdminLTE 2-inspired</span></span></a>
        <div class="mt-6 rounded-xl border border-background/10 bg-background/5 p-3"><div class="flex items-center gap-3"><span class="avatar h-10 w-10 rounded-xl bg-primary text-primary-foreground">MR</span><div><p class="text-sm font-semibold text-background">Maya Rahman</p><p class="text-xs font-medium text-background/70">online - admin</p></div></div></div>
        <nav class="mt-6 grid gap-1 text-sm" aria-label="Admin sections">${desktopNav}</nav>
      </aside>
      <div class="min-w-0">
        <header class="sticky top-0 z-30 border-b border-border/80 bg-background/95 shadow-sm backdrop-blur"><div class="flex flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6"><div class="flex min-w-0 grow items-center gap-2 lg:grow-0"><button class="btn btn-outline-secondary h-9 shrink-0 px-3 text-sm lg:hidden" type="button" data-bs-toggle="offcanvas" data-bs-target="#mobileNav" aria-controls="mobileNav">Menu</button><label class="sr-only" for="adminSearch">Search</label><input id="adminSearch" class="form-control w-full shadow-none sm:w-80" placeholder="Search orders, users, invoices"></div><div class="flex items-center gap-2"><div class="dropdown"><button class="btn btn-outline-secondary h-9 px-3 text-sm dropdown-toggle" type="button" data-bs-toggle="dropdown">Messages <span class="badge badge-info">4</span></button><div class="dropdown-menu dropdown-menu-end"><button class="dropdown-item" type="button">Support replied</button><button class="dropdown-item" type="button">New lead message</button></div></div><div class="dropdown"><button class="btn btn-outline-secondary h-9 px-3 text-sm dropdown-toggle" type="button" data-bs-toggle="dropdown">Tasks <span class="badge badge-warning">7</span></button><div class="dropdown-menu dropdown-menu-end"><button class="dropdown-item" type="button">Review queue</button><button class="dropdown-item" type="button">Ship report</button></div></div></div></div></header>
        <main class="mx-auto w-full max-w-screen-2xl space-y-6 p-4 sm:p-6 lg:p-8">${body}</main>
      </div>
    </div>
    <div id="mobileNav" class="offcanvas offcanvas-start border-background/10 bg-foreground text-background" tabindex="-1" aria-labelledby="mobileNavTitle"><div class="flex items-center justify-between border-b border-background/10 bg-background/5 px-4 py-4"><a class="flex items-center gap-3 rounded-xl px-2 py-2 text-background transition-colors hover:bg-background/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-foreground" href="index.html" aria-label="Windform admin home"><span class="inline-flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary font-bold text-primary-foreground shadow-sm">WF</span><span><span id="mobileNavTitle" class="block font-semibold text-background">Windform Admin</span><span class="block text-sm text-background/70">AdminLTE 2-inspired</span></span></a><button class="inline-flex h-9 w-9 items-center justify-center rounded-lg text-background/70 hover:bg-background/10 hover:text-background" type="button" data-bs-dismiss="offcanvas" aria-label="Close"><span aria-hidden="true">×</span></button></div><div class="p-4"><div class="rounded-xl border border-background/10 bg-background/5 p-3"><div class="flex items-center gap-3"><span class="avatar h-10 w-10 rounded-xl bg-primary text-primary-foreground">MR</span><div><p class="text-sm font-semibold text-background">Maya Rahman</p><p class="text-xs font-medium text-background/70">online - admin</p></div></div></div><nav class="mt-6 grid gap-1 text-sm" aria-label="Admin sections">${mobileNav}</nav></div></div>
    ${extra}
  </body>
</html>
`;
}

function head(eyebrow, h1, desc) {
  return `<section class="rounded-2xl border border-border bg-background p-5 shadow-sm sm:p-6"><p class="text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">${eyebrow}</p><h1 class="mt-2 text-3xl font-semibold tracking-tight sm:text-4xl">${h1}</h1><p class="mt-2 max-w-3xl text-muted-foreground">${desc}</p></section>`;
}

